/**
 * LLM Pricing Registry
 * Prices are in USD per 1,000,000 tokens (input / output / cache).
 * Cache read/write prices default to input price when not specified.
 * Source: Helicone Open Source Cost Registry & Provider Official Pricing.
 * Total models tracked: 852+
 */

export interface ModelPrice {
  inputCostPer1M: number;
  outputCostPer1M: number;
  cacheReadCostPer1M?: number;   // defaults to inputCostPer1M
  cacheWriteCostPer1M?: number;  // defaults to inputCostPer1M
  contextLength?: number;
  maxOutputTokens?: number;
  provider?: string;
}

export interface UsageInput {
  promptTokens?: number | null;
  completionTokens?: number | null;
  promptCacheReadTokens?: number | null;
  promptCacheWriteTokens?: number | null;
}

export interface CostResult {
  inputCost: number | null;
  outputCost: number | null;
  cost: number | null;
  costDetails: Record<string, number>;
}

