/**
 * Find pricing for a model by exact match then prefix match.
 * Handles dated suffix variants (e.g. 'gpt-4o-2024-11-20' → 'gpt-4o').
 */
export function findPricing(model: string): ModelPrice | null {
  if (!model) return null;
  const key = model.toLowerCase().trim();

  // 1. Exact match
  if (PRICING[key]) return PRICING[key];

  // 2. Prefix match (longest matching prefix wins)
  let best: ModelPrice | null = null;
  let bestLen = 0;
  for (const [prefix, price] of Object.entries(PRICING)) {
    if (key.startsWith(prefix) && prefix.length > bestLen) {
      best = price;
      bestLen = prefix.length;
    }
  }
  return best;
}

/**
 * Calculate USD costs from token usage.
 * Returns null costs when model pricing is unknown.
 */
export function calculateCost(model: string, usage: UsageInput): CostResult {
  const pricing = findPricing(model);

  if (!pricing) {
    return { inputCost: null, outputCost: null, cost: null, costDetails: {} };
  }

  const promptTokens        = usage.promptTokens ?? 0;
  const completionTokens    = usage.completionTokens ?? 0;
  const cacheReadTokens     = usage.promptCacheReadTokens ?? 0;
  const cacheWriteTokens    = usage.promptCacheWriteTokens ?? 0;

  // Regular input = total prompt tokens minus cached tokens
  const regularInputTokens  = Math.max(0, promptTokens - cacheReadTokens);

  const inputCostRaw        = (regularInputTokens  / 1_000_000) * pricing.inputCostPer1M;
  const cacheReadCostRaw    = (cacheReadTokens     / 1_000_000) * (pricing.cacheReadCostPer1M ?? pricing.inputCostPer1M);
  const cacheWriteCostRaw   = (cacheWriteTokens    / 1_000_000) * (pricing.cacheWriteCostPer1M ?? pricing.inputCostPer1M);
  const outputCostRaw       = (completionTokens    / 1_000_000) * pricing.outputCostPer1M;

  const totalInputCost      = inputCostRaw + cacheReadCostRaw + cacheWriteCostRaw;
  const totalCost           = totalInputCost + outputCostRaw;

  const costDetails: Record<string, number> = {};
  if (inputCostRaw)      costDetails.input       = inputCostRaw;
  if (cacheReadCostRaw)  costDetails.cache_read   = cacheReadCostRaw;
  if (cacheWriteCostRaw) costDetails.cache_write  = cacheWriteCostRaw;
  if (outputCostRaw)     costDetails.output       = outputCostRaw;

  return {
    inputCost:  totalInputCost,
    outputCost: outputCostRaw,
    cost:       totalCost,
    costDetails,
  };
}
